    "supplier.req.title": "Richiesta per il fornitore: testo pronto da copiare",
    "supplier.req.desc": "Genera una comunicazione formale indirizzata al tuo fornitore di gioielli per ottenere la documentazione di conformità prescritta.",
    "supplier.field.name": "Referente / Ragione sociale del fornitore",
    "supplier.field.items": "Articoli di gioielleria / Codici catalogo",
    "supplier.btn.copy": "Copia testo della richiesta",
