    "studio.validation.sku_required": "Bitte geben Sie eine Artikelnummer / SKU an, um das Konformitätsblatt zu drucken.",
    "studio.print.title": "Studio-Konformitätsblatt für Piercingschmuck",
    "studio.print.subtitle": "Prüfnachweis gemäß REACH Anhang XVII Eintrag 27 und EN 1811:2023",
    "studio.print.meta_studio": "Studio-Name:",
    "studio.print.meta_date": "Datum:",
